.kpi.t{ } .kpi.t:before{background:var(--teal)} .kpi.r:before{background:var(--red)}
.kpi.g:before{background:var(--green)} .kpi.v:before{background:var(--violet)} .kpi.b:before{background:var(--blue)}
.kpi .lab{font-size:10px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);font-weight:700;}
.kpi .val{font-size:29px;font-weight:600;letter-spacing:-.8px;margin:5px 0 1px;font-family:'Iowan Old Style',Georgia,serif;}
.kpi .val small{font-size:14px;font-weight:400;color:var(--muted);}
.kpi .note{font-size:12px;color:var(--muted);line-height:1.4;}
.delta{font-size:12px;font-weight:700;} .up{color:var(--green)} .dn{color:var(--red)} .fl{color:var(--muted)}
/* ---------- CARD / PANEL ---------- */
.card{background:var(--card);border:1px solid var(--line);border-radius:7px;padding:22px 24px;margin:18px 0;}
.card.alt{background:#FBF9F6;}
.card h4{margin:0 0 10px;font-size:17px;}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:18px;}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;}
@media(max-width:900px){.grid2,.grid3{grid-template-columns:1fr}}
/* ---------- TABLE ---------- */
.tbl-wrap{overflow-x:auto;margin:14px 0 6px;border:1px solid var(--line);border-radius:6px;background:#fff;}
table{border-collapse:collapse;width:100%;font-size:12.5px;}
th{background:#F1EDE6;text-align:left;padding:9px 10px;font-size:10px;letter-spacing:.09em;text-transform:uppercase;
 color:var(--ink2);font-weight:800;border-bottom:1px solid var(--line);white-space:nowrap;position:sticky;top:0;}
td{padding:8px 10px;border-bottom:1px solid var(--line2);vertical-align:top;}
tbody tr:hover{background:#FBF9F5;}
tr.tot td{background:#F1EDE6;font-weight:700;border-top:2px solid var(--line);}
td.n,th.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;}
td.c,th.c{text-align:center;}
.name{font-weight:700;color:var(--ink);white-space:nowrap;}
.mono{font-variant-numeric:tabular-nums;}
.pill{display:inline-block;font-size:10px;font-weight:800;letter-spacing:.06em;padding:2px 7px;border-radius:10px;text-transform:uppercase;}
.p-good{background:var(--green-l);color:var(--green)} .p-warn{background:var(--gold-l);color:#8A6520}
.p-bad{background:var(--red-l);color:var(--red)} .p-neu{background:#ECEFF2;color:#54646F}
.p-teal{background:var(--teal-l);color:var(--teal)} .p-vio{background:var(--violet-l);color:var(--violet)}
.p-blue{background:var(--blue-l);color:var(--blue)}
/* ---------- INSIGHT ---------- */
.ins{border-left:3px solid var(--gold);background:#fff;border:1px solid var(--line);border-left-width:3px;
 border-radius:0 6px 6px 0;padding:16px 20px;margin:16px 0;}
.ins.red{border-left-color:var(--red)} .ins.teal{border-left-color:var(--teal)}
.ins.vio{border-left-color:var(--violet)} .ins.green{border-left-color:var(--green)}
.ins .t{font-family:'Iowan Old Style',Georgia,serif;font-size:17px;font-weight:600;margin-bottom:9px;color:var(--ink);}
.ins dl{margin:0;display:grid;grid-template-columns:132px 1fr;gap:5px 14px;font-size:13.5px;}
.ins dt{font-size:10px;letter-spacing:.11em;text-transform:uppercase;font-weight:800;color:var(--gold);padding-top:4px;}
.ins.red dt{color:var(--red)} .ins.teal dt{color:var(--teal)} .ins.vio dt{color:var(--violet)} .ins.green dt{color:var(--green)}
.ins dd{margin:0;}
/* ---------- CALLOUT ---------- */
.callout{background:var(--ink);color:#E9EFF4;border-radius:7px;padding:20px 24px;margin:22px 0;}
.callout h4{color:var(--gold);margin:0 0 8px;font-size:13px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;}
.callout p{color:#C9D5DE;font-size:14px;}
.callout b{color:#fff;}
/* ---------- MISC ---------- */
ul.tick{list-style:none;padding-left:0;margin:8px 0;}
ul.tick li{position:relative;padding-left:20px;margin-bottom:7px;font-size:14px;}
ul.tick li:before{content:'';position:absolute;left:0;top:8px;width:7px;height:7px;background:var(--gold);border-radius:50%;}
.cap{font-size:11.5px;color:var(--muted2);margin-top:6px;font-style:italic;}
.tag{display:inline-block;font-size:10px;font-weight:800;letter-spacing:.1em;padding:2px 8px;border-radius:3px;
 text-transform:uppercase;background:#ECEFF2;color:#54646F;margin-right:6px;}
.tag.hi{background:var(--red-l);color:var(--red)} .tag.md{background:var(--gold-l);color:#8A6520}
.tag.lo{background:#ECEFF2;color:#54646F}
.foot{margin-top:60px;padding-top:22px;border-top:1px solid var(--line);font-size:12px;color:var(--muted2);}
svg{display:block;max-width:100%;height:auto;}
.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:11.5px;color:var(--muted);margin-top:8px;align-items:center;}
.legend i{display:inline-block;width:11px;height:11px;border-radius:2px;margin-right:5px;vertical-align:-1px;}
.toc{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:10px;margin:24px 0 0;}
.toc a{display:block;background:#fff;border:1px solid var(--line);border-radius:5px;padding:11px 14px;
 text-decoration:none;color:var(--ink2);font-size:13.5px;font-weight:600;}
.toc a span{display:block;font-size:10px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold);font-weight:800;margin-bottom:2px;}
.toc a:hover{border-color:var(--gold);background:#FDFBF7;}
